-- Extensions to fixtures/seondo.sql for a disposable test database.
create table core.staff_accounts (id uuid primary key, display_name text not null, is_active boolean default true);
create function private.current_homeroom_staff() returns uuid language sql stable as $$
  select id from core.staff_accounts where id=auth.uid() and is_active
$$;
create type public.point_type as enum ('POSITIVE','NEGATIVE');
alter table public.point_records alter column id add generated by default as identity;
alter table public.point_records add column entered_by_name text, add column source_type text, add column source_key text unique;
